/// Builds the CodeFlowEngine. Dropped parameters: none.
pub fn get_code_flow_engine(
    evaluator: P<TypeEvaluator>,
    speculative_type_tracker: P<RefCell<SpeculativeTypeTracker>>,
    node_info: Rc<AnalyzerNodeInfoAccessor>,
) -> P<CodeFlowEngine> {
    let engine = P::new_eval(CodeFlowEngine {
        evaluator,
        speculative_type_tracker,
        node_info,
        is_reachable_recursion_set: RefCell::new(JsSet::default()),
        reachability_cache: RefCell::new(FxHashMap::default()),
        call_is_no_return_cache: RefCell::new(JsMap::default()),
        is_exception_context_manager_cache: RefCell::new(JsMap::default()),
        flow_incomplete_generation: Cell::new(1),
        no_return_analysis_depth: Cell::new(0),
        context_manager_analysis_depth: Cell::new(0),
        max_convergence_limit_hit: Cell::new(false),
        handle: OnceCell::new(),
    });
    let _ = engine.handle.set(engine);
    engine
}

