            // (nested) analyzer/codeFlowEngine.ts:943 getTypeFromBranchFlowNode
            fn get_type_from_branch_flow_node(&self, branch_node: FlowLabel) -> FlowNodeTypeResult {
                let mut types_to_combine: Vec<P<Type>> = Vec::new();

                let mut saw_incomplete = false;

                let antecedents = branch_node.d().antecedents.borrow().clone();
                for antecedent in antecedents {
                    let flow_type_result = self.get_type_from_flow_node(antecedent);

                    if self.reference.is_none()
                        && flow_type_result.type_.is_some_and(|type_| !is_never(type_))
                    {
                        // If we're solving for "reachability", and we have now proven
                        // reachability, there's no reason to do more work. The type we
                        // return here doesn't matter as long as it's not undefined.
                        return self.set_cache_entry(
                            branch_node.0,
                            Some(UnknownType::create(false).0),
                            false,
                        );
                    }

                    if flow_type_result.is_incomplete {
                        saw_incomplete = true;
                    }

                    if let Some(type_) = flow_type_result.type_ {
                        types_to_combine.push(type_);
                    }
                }

                let effective_type = if !types_to_combine.is_empty() {
                    Some(combine_types(&types_to_combine, None))
                } else {
                    None
                };

                self.set_cache_entry(branch_node.0, effective_type, saw_incomplete)
            }

